/**
 * QA-only manifest attestation gate. Ed25519 keypair is generated by the
 * outside test runner. The private key NEVER enters Worker/DO runtime or repo.
 * This is proof of signing-key possession, NOT a production DWD source issuer.
 */
import {sha256,validateManifest} from "./ruc_do_worker_core_qa.mjs";

function fail(reason){throw Error("MID DO attestation BLOCKED: "+reason);}
const encoder=new TextEncoder();
export function decodeBase64Strict(s,size){
  if(typeof s!=="string"||s.length>512||!/^[A-Za-z0-9+/]+={0,2}$/.test(s))
    fail("invalid encoded signature/key");
  let raw;
  try{raw=atob(s);}catch{fail("invalid base64");}
  const bytes=Uint8Array.from(raw,x=>x.charCodeAt(0));
  if(bytes.length!==size || btoa(raw)!==s)fail("noncanonical base64 or length");
  return bytes;
}
export async function signedManifestMessage(m){
  validateManifest(m);
  // JSON.stringify is deliberately the exact wire-format contract. A signer
  // must sign the payload returned by THIS function, not arbitrary JSON.
  const sourceDigest=await sha256(encoder.encode(JSON.stringify(m)));
  return JSON.stringify({
    schema:"mid.ruc.do.signed-manifest-qa.v1",
    sourceRun:m.run,
    producerCommitSha:m.sourceSha,
    externalArtifactProofSha256:m.sourceProofSha256,
    serializedManifestSha256:sourceDigest,
    timeCount:28,epsMembers:20,
    qaOnly:true,
  });
}
export async function verifySignedManifestQa(m,signatureB64,rawPublicKeyB64){
  const publicBytes=decodeBase64Strict(rawPublicKeyB64,32);
  const signature=decodeBase64Strict(signatureB64,64);
  const message=encoder.encode(await signedManifestMessage(m));
  let key;
  try{
    key=await crypto.subtle.importKey("raw",publicBytes,{name:"Ed25519"},false,["verify"]);
  }catch{fail("trusted public key unsupported or invalid");}
  let valid=false;
  try{valid=await crypto.subtle.verify({name:"Ed25519"},key,signature,message);}
  catch{fail("Ed25519 verification failed");}
  if(!valid)fail("untrusted issuer or modified manifest");
  return {verified:true,manifestSha256:await sha256(encoder.encode(JSON.stringify(m))),
    qaOnly:true,productionApproved:false,activationAuthorized:false};
}